#include "resident/domains/interaction/interaction_source_projection.hpp"
// 仅原实际provider与作者模板；静态两端不强造Birth，任一出生选择须原Birth/Lineage真实配对。
#include "known_personal_dialogue_boundary.hpp"
#include <set>
namespace hanmo::resident {namespace {
void unique(const BoundaryValue& v,const StableId& path){std::set<StableId> keys;for(const auto& row:boundary::object(v,path))if(!keys.insert(row.first).second)boundary::fail("DuplicateKnownPersonalDialogueField",path+"/"+row.first);}
}
Outcome<OpenKnownPersonalDialogue> decode_known_personal_dialogue_command(const StableId& kind,const BoundaryValue& value){try{using namespace boundary;if(kind!="open_known_personal_dialogue")unsupported("UnsupportedKnownPersonalDialogueCommand",kind);unique(value,kind);fields(value,{"provider_actor_id","template_id"},{},kind);OpenKnownPersonalDialogue out{get_string(value,"provider_actor_id",kind),get_string(value,"template_id",kind)};if(out.provider_actor_id.empty()||out.provider_actor_id.size()>256||out.template_id.empty()||out.template_id.size()>256)fail("InvalidKnownPersonalDialogueCommand",kind);return {true,std::move(out),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
BoundaryValue encode_known_personal_dialogue_command(const OpenKnownPersonalDialogue& c){return boundary::obj({{"provider_actor_id",BoundaryValue{c.provider_actor_id}},{"template_id",BoundaryValue{c.template_id}}});}
BoundaryValue encode_known_personal_dialogue_quote(const KnownPersonalDialogueQuote& q){return boundary::obj({{"duration",BoundaryValue{Integer{0}}},{"template_id",BoundaryValue{q.template_id}},{"provider_actor_id",BoundaryValue{q.context.provider_actor_id}},{"dialogue_id",BoundaryValue{q.dialogue_id}},{"place_id",BoundaryValue{q.context.place_id}}});}
bool known_personal_dialogue_needs_birth(const KnownPersonalDialogueCatalog& catalog){for(const auto& t:catalog.templates)if(t.listener.kind=="born_prototype"||t.provider.kind=="born_prototype")return true;return false;}
Outcome<bool> decode_known_personal_dialogue_profile(const BoundaryValue& scenario,const std::vector<StableId>& capabilities){try{using namespace boundary;unique(scenario,"scenario");const auto* dynamic=scenario.find("dynamic_world");if(!dynamic)return {true,false,{}};unique(*dynamic,"dynamic_world");const auto* config=dynamic->find("known_personal_dialogues");if(!config)return {true,false,{}};if(get_string(*dynamic,"profile","dynamic_world")!="local_society_v1")unsupported("KnownPersonalDialogueNativeProfileRequired","dynamic_world");unique(*config,"known_personal_dialogues");fields(*config,{"version","templates"},{},"known_personal_dialogues");if(get_int(*config,"version","known_personal_dialogues")!=1)unsupported("UnsupportedKnownPersonalDialogueVersion","known_personal_dialogues");for(const auto* cap:{"known_personal_dialogues_v1","dialogue","multi_actor","native_dynamic_world"})if(std::find(capabilities.begin(),capabilities.end(),cap)==capabilities.end())unsupported("KnownPersonalDialogueCapabilityRequired",cap);if(!scenario.find("family_life"))unsupported("KnownPersonalDialogueLifeProfileRequired","known_personal_dialogues");bool birth=false;for(const auto& row:array(field(*config,"templates","known_personal_dialogues"),"templates"))for(const auto* endpoint:{"listener","provider"})if(get_string(field(row,endpoint,"template"),"kind",endpoint)=="born_prototype")birth=true;if(birth&&(!scenario.find("family_birth")||!scenario.find("family_lineage")||std::find(capabilities.begin(),capabilities.end(),"family_birth_v1")==capabilities.end()))unsupported("KnownPersonalDialogueBirthProfileRequired","known_personal_dialogues");return {true,true,{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Outcome<bool> known_personal_dialogue_selected(const std::vector<std::pair<StableId,StableId>>& modules){Integer own=0,life=0;bool valid_life=true;for(const auto& m:modules){if(m.first==known_personal_dialogue_module){++own;if(m.second!="1")return {false,{},common_failure("UnsupportedKnownPersonalDialogueVersion").error};}if(m.first=="family_life"){++life;if(m.second!="1")valid_life=false;}}if(own>1||(own&&(life!=1||!valid_life)))return {false,{},common_failure("KnownPersonalDialogueProfileMismatch").error};return {true,own==1,{}};}
Status validate_known_personal_dialogue_layout(const CommonStore& common,const std::vector<std::pair<StableId,StableId>>& modules,const KnownPersonalDialogueCatalog* catalog,const KnownPersonalDialogueState* state){auto selected=known_personal_dialogue_selected(modules);if(!selected.ok)return {false,{},selected.error};if(selected.value!=bool(catalog)||bool(catalog)!=bool(state)||(catalog&&catalog->version!=1)||(state&&state->version!=1))return common_failure("KnownPersonalDialogueProfileMismatch");if(catalog&&known_personal_dialogue_needs_birth(*catalog)){Integer birth=0,lineage=0;for(const auto& m:modules){if(m.first=="family_birth"){if(m.second!="1")return common_failure("KnownPersonalDialogueBirthProfileRequired");++birth;}if(m.first=="family_lineage"){if(m.second!="1")return common_failure("KnownPersonalDialogueBirthProfileRequired");++lineage;}}if(birth!=1||lineage!=1)return common_failure("KnownPersonalDialogueBirthProfileRequired");}if(state)return common_success();for(const auto& h:common.state().facts.rows())if(h.second.domain==known_personal_dialogue_module||h.second.kind==known_personal_dialogue_opened_kind)return common_failure("KnownPersonalDialogueProfileRequired",h.first);return validate_known_personal_dialogue_cached_results(common,nullptr);}
Outcome<bool> emit_known_personal_dialogue_fact_payload_fields(ProjectionWriter& w,const KnownPersonalDialogueState* state,const FactRecord& h){if(h.domain!=known_personal_dialogue_module&&h.kind!=known_personal_dialogue_opened_kind)return {true,false,{}};if(!state||h.domain!=known_personal_dialogue_module||h.kind!=known_personal_dialogue_opened_kind)return {false,{},common_failure("KnownPersonalDialogueFactMismatch",h.id).error};auto status=emit_known_personal_dialogue_fact_fields(w,*state,h.id,&h);if(!status.ok)return {false,{},status.error};return {w.status().ok,w.status().ok,w.status().error};}
Status emit_known_personal_dialogue_fact_payloads_fields(ProjectionWriter& w,const CommonStore& common,const KnownPersonalDialogueState* state){std::size_t emitted=0;for(const auto& row:common.state().facts.rows()){const auto& h=row.second;if(h.domain!=known_personal_dialogue_module&&h.kind!=known_personal_dialogue_opened_kind)continue;if(!state||h.id!=row.first||h.domain!=known_personal_dialogue_module||h.kind!=known_personal_dialogue_opened_kind)return common_failure("KnownPersonalDialogueFactMismatch",row.first);auto checked=w.object(row.first,h.field_order,[&](auto&out){return emit_known_personal_dialogue_fact_fields(out,*state,row.first,&h);});if(!checked.ok)return checked;++emitted;}if(state&&emitted!=state->openings.size())return common_failure("KnownPersonalDialogueFactCoverageMismatch");return w.status();}
Outcome<BoundaryValue> known_personal_dialogue_fact_payloads(const CommonStore& common,const KnownPersonalDialogueState* state){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto&out){return emit_known_personal_dialogue_fact_payloads_fields(out,common,state);});if(checked.ok)checked=writer.finish();return checked.ok?Outcome<BoundaryValue>{true,std::move(value),{}}:Outcome<BoundaryValue>{false,{},checked.error};}
Status validate_known_personal_dialogue_json_payloads(const CommonStore& common,const KnownPersonalDialogueState* state,const BoundaryValue& value){try{using namespace boundary;auto expected=known_personal_dialogue_fact_payloads(common,state);if(!expected.ok)return {false,{},expected.error};for(const auto& row:object(expected.value,"known_personal_dialogues/facts"))if(!compare_boundary(field(field(value,"facts","state"),row.first,"facts"),row.second).exact())return common_failure("KnownPersonalDialogueFactPayloadMismatch",row.first);return common_success();}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
}
